    scope(book, chapter); const source = snapshot.json(`data/${book}/${chapter}.json`), raw = snapshot.json(`data/people/extractions/${book}/${chapter}.json`), report = snapshot.json(`data/people/date-audits/${book}/${chapter}.json`);
