    const packet = { schemaVersion: 1, auditVersion: DATE_AUDIT_VERSION, book, chapter, units, sourceHash: sha256(JSON.stringify(units)), extractionHash: sha256(JSON.stringify(raw)), extractor: raw.run, ...dateAuditItems(raw) };
