import { buildPeopleExtractionPacket } from '../build-people-extraction-packet.mjs';
import { validateCompactPeopleExtraction, validatePeopleExtraction } from '../validate-people-extraction.mjs';
import { isCompactPeopleExtraction } from './people-compact.mjs';
import { extractionPath, readJson } from './people-content.mjs';

export function peopleForExtraction(extraction) {
  const claims = new Map(), mentions = new Map();
  for (const claim of extraction.claims) { if (!claims.has(claim.subject)) claims.set(claim.subject, []); claims.get(claim.subject).push(claim); }
  for (const mention of extraction.mentions) { if (!mentions.has(mention.person)) mentions.set(mention.person, []); mentions.get(mention.person).push(mention); }
  const people = new Map();
  for (const person of extraction.people) {
    if (people.has(person.localId)) throw new Error(`Duplicate source person ${person.localId}`);
    people.set(person.localId, { ...person, book: extraction.book, chapter: extraction.chapter,
      promptVersion: extraction.run.promptVersion, claims: claims.get(person.localId) ?? [], mentions: mentions.get(person.localId) ?? [] });
  }
  return people;
}

export function loadValidatedPeopleChapter(book, chapter, { properNounMatcher, strictAliasDispositions = true } = {}) {
  const raw = readJson(extractionPath(book, chapter));
  if (raw.book !== book || raw.chapter !== chapter) throw new Error(`Extraction scope mismatch: ${book}:${chapter}`);
  const packet = buildPeopleExtractionPacket(book, chapter, { properNounMatcher });
  const options = { strictAliasDispositions };
  const { normalized: extraction } = isCompactPeopleExtraction(raw)
    ? validateCompactPeopleExtraction(raw, packet, options) : validatePeopleExtraction(raw, packet, options);
  return { raw, packet, extraction, localPeople: peopleForExtraction(extraction) };
}

import fs from 'node:fs';
import path from 'node:path';
import { DATA_DIR, PEOPLE_DIR, contentUnits, readJson, sha256, writeJsonAtomic } from './people-content.mjs';
import { temporalContainers, westernBoundsErrors, westernYearOrder } from './people-date-values.mjs';
import { personClaimReception, personReceptionErrors } from './people-reception.mjs';

export const DATE_AUDIT_VERSION = 1;
export const DATE_AUDIT_STATES = ['un-audited', 'audited', 'needs-revision', 'research-blocked', 'stale'];
const TEMPORAL_KEYS = new Set(['westernYear', 'westernInterval', 'westernBounds', 'sourceDate', 'dateContext', 'startDate', 'endDate']);
const LIFE_PREDICATES = new Set(['attestation', 'birth', 'death', 'age']);

export function validateDateAuditScope(book, chapter) {
  if (!/^[a-z0-9_-]+$/.test(book) || !/^\d{3}$/.test(chapter)) throw new Error('Date audit requires book and three-digit chapter');
}

function hasTemporalValue(value) {
  return value && typeof value === 'object' && Object.entries(value).some(([key, child]) => TEMPORAL_KEYS.has(key) || hasTemporalValue(child));
}

// Shared approval/scheduling predicate: bounded or explicitly undated values do
// not count as unresolved unless their temporal container says so.
export function unresolvedDateAuditItems(packet) {
  return packet.items.filter(item => temporalContainers(item.value).some(value => value.unresolved === true));
}

export function dateAuditDiagnostics(packet) {
  return packet.items.flatMap(item => {
    const errors = personReceptionErrors(item);
    for (const value of temporalContainers(item.value)) {
      const interval = value.westernInterval;
      if (interval?.start && interval?.end && westernYearOrder(interval.start) > westernYearOrder(interval.end)) errors.push('Western interval is reversed; verify era and endpoints against the source.');
      if (value.westernBounds) errors.push(...westernBoundsErrors(value.westernBounds));
    }
    return errors.map(problem => ({ item: item.id, personId: item.personId, problem }));
  });
}

export function dateAuditItems(extraction) {
  const compact = extraction.schemaVersion === 2;
  const people = extraction.people.map(person => compact
    ? { id: person[0], names: person[1], historicity: person[2], descriptor: person[3], hints: person[4]?.a ?? [] }
    : { id: person.localId, names: person.preferredName, historicity: person.historicity, descriptor: person.description, hints: person.identityHints?.activeDateHints ?? [] });
  const items = extraction.claims.flatMap((claim, index) => {
    const [personId, predicate, value, certainty, evidence] = compact
      ? claim : [claim.subject, claim.predicate, claim.value, claim.certainty, claim.evidence];
    if (!LIFE_PREDICATES.has(predicate) && !hasTemporalValue(value) && !personClaimReception({ value }) &&
        !personReceptionErrors({ predicate, value }).length) return [];
    return [{ id: `claim-${index + 1}`, claimIndex: index, personId, predicate, value, certainty,
      evidence: evidence.map(id => id.split(':').at(-1)), claimHash: sha256(JSON.stringify(claim)) }];
  });
  for (const person of people) items.push({ id: `hints-${person.id}`, personId: person.id, predicate: 'active-date-hints', value: person.hints, evidence: [] });
  return { people, items };
}

// A repair candidate must cover every still-incorrect, repairable record named by
// the audit, even when the reviewer separated related findings into later groups.
// Keep this selection here rather than letting one-off staging scripts accidentally
// treat the first finding as the entire repair scope.
export function actionableDateAuditItems(report) {
  if (!Array.isArray(report?.findings) || !Array.isArray(report?.itemChecks)) throw new Error('Date audit report lacks findings or item checks');
  const verdictById = new Map(report.itemChecks.map(check => [check.id, check.verdict]));
  const selected = [];
  const seen = new Set();
  for (const finding of report.findings) {
    if (!Array.isArray(finding.items)) throw new Error('Date audit finding lacks item IDs');
    for (const id of finding.items) {
      if (!/^(claim-\d+|hints-p\d+)$/.test(id) || verdictById.get(id) !== 'incorrect' || seen.has(id)) continue;
      seen.add(id);
      selected.push(id);
    }
  }
  return selected;
}

export function buildDateAuditPacket(book, chapter, { dataDir = DATA_DIR, peopleDir = PEOPLE_DIR, extraction: suppliedExtraction } = {}) {
  validateDateAuditScope(book, chapter);
  const source = readJson(path.join(dataDir, book, `${chapter}.json`));
  const extraction = suppliedExtraction ?? readJson(path.join(peopleDir, 'extractions', book, `${chapter}.json`));
  if (extraction.book !== book || extraction.chapter !== chapter) throw new Error('Date audit extraction scope mismatch');
  const units = contentUnits(source).map(({ id, zh, en, literal, blockIndex }) => ({ id, zh, en, literal, blockIndex }));
  const { people, items } = dateAuditItems(extraction);
  const unitIds = new Set(units.map(unit => unit.id));
  const unitPeople = Object.fromEntries(units.map(u=>[u.id,[]]));
  const mention = (unit, person) => { if(unitPeople[unit] && !unitPeople[unit].includes(person))unitPeople[unit].push(person); };
  if(extraction.schemaVersion===2) for(const row of extraction.surfaces??[]) for(const occurrence of row[4])mention(occurrence[0],row[0]);
  else for(const m of extraction.mentions??[])mention(m.unit.id.split(':').at(-1),m.person);
  for (const item of items) if (item.evidence.some(id => !unitIds.has(id))) throw new Error(`Unknown date evidence in ${item.id}`);
  return { schemaVersion: 1, auditVersion: DATE_AUDIT_VERSION, book, chapter,
    sourceHash: sha256(JSON.stringify(units)), extractionHash: sha256(JSON.stringify(extraction)),
    sourceUrl: source.meta?.url ?? null, extractor: extraction.run, people, items, units, unitPeople,
    instructions: 'Review dates, event ownership, conversions, endpoint evidence, age reckoning, omitted life dates, and active-date hints. Read all Chinese units for omissions; English is not independent evidence. Do not re-extract names or mentions. For each item identify whose event is dated and justify each endpoint. Same mother does not imply same birth year. Later allusions are not personal activity. Research or record a blocker rather than invent precision. A report cannot approve with missing checks or unresolved research.' };
}

function nonempty(value, label, minimum = 1) {
  if (typeof value !== 'string' || value.trim().length < minimum) throw new Error(`${label} must be substantive text`);
}

function exactMembers(actual, expected, label, complete) {
  if (!Array.isArray(actual) || new Set(actual).size !== actual.length || actual.some(id => !expected.includes(id))) throw new Error(`${label} contains duplicate or unknown IDs`);
  if (complete && actual.length !== expected.length) throw new Error(`${label} does not cover the complete chapter`);
}

// Diagnostic only: malformed check collections still require full validation.
export function dateAuditReasonErrors(report) {
  if (!Array.isArray(report?.itemChecks) || !Array.isArray(report?.personChecks)) return [];
  const checks = [...report.itemChecks, ...report.personChecks];
  if (checks.some(check => !check || typeof check.id !== 'string')) return [];
  return checks.filter(check => typeof check.reason !== 'string' || check.reason.trim().length < 20)
    .map(check => `Reason for ${check.id} must be substantive text`);
}

export function validateDateAuditReport(report, packet) {
  if (report.schemaVersion !== 1 || report.auditVersion !== DATE_AUDIT_VERSION || report.book !== packet.book || report.chapter !== packet.chapter) throw new Error('Date audit report version or scope mismatch');
  if (report.sourceHash !== packet.sourceHash || report.extractionHash !== packet.extractionHash) throw new Error('Date audit report is stale');
  if (!['audited', 'needs-revision', 'research-blocked'].includes(report.status)) throw new Error('Invalid date audit report status');
  nonempty(report.reviewer?.name, 'Reviewer');
  if (report.reviewer?.independentOfExtractor !== true) throw new Error('Date audit requires a separate source reviewer');
  if (!Number.isFinite(Date.parse(report.reviewedAt))) throw new Error('Invalid date audit timestamp');
  nonempty(report.summary, 'Audit summary', 20);
  if (!Array.isArray(report.itemChecks) || !Array.isArray(report.personChecks) || !Array.isArray(report.findings) || !Array.isArray(report.references)) throw new Error('Missing date audit checks, findings, or references');
  const complete = report.status === 'audited';
  if (complete && dateAuditDiagnostics(packet).length) throw new Error('Date approval retains invalid temporal geometry or reception ownership');
  exactMembers(report.reviewedUnits, packet.units.map(unit => unit.id), 'Reviewed units', complete);
  exactMembers(report.itemChecks.map(item => item.id), packet.items.map(item => item.id), 'Date checks', complete);
  exactMembers(report.personChecks.map(person => person.id), packet.people.map(person => person.id), 'Person checks', complete);
  // Returning only the first missing ownership field turns an otherwise complete
  // sealed review into one expensive continuation per hint. Surface every absent
  // item event at once so the retained independent reviewer can repair one exact
  // artifact without the host weakening the substantive-event requirement.
  const missingItemEvents = report.itemChecks
    .filter(check => typeof check.event !== 'string' || check.event.trim().length < 10)
    .map(check => check.id);
  if (missingItemEvents.length) {
    throw new Error(`Event ownership must be substantive text for: ${missingItemEvents.join(', ')}`);
  }
  const invalidReasons = dateAuditReasonErrors(report);
  if (invalidReasons.length) throw new Error(invalidReasons.join('; '));
  const unitMap = new Map(packet.units.map(unit => [unit.id, unit]));
  for (const check of [...report.itemChecks, ...report.personChecks]) {
    if (!['supported', 'incorrect', 'research-blocked'].includes(check.verdict)) throw new Error(`Invalid verdict for ${check.id}`);
    if (report.itemChecks.includes(check)) nonempty(check.event, `Event ownership for ${check.id}`, 10);
    if (!Array.isArray(check.evidence) || !check.evidence.length) throw new Error(`Missing evidence for ${check.id}`);
    for (const citation of check.evidence) {
      nonempty(citation.quote, 'Source quotation');
      if (!unitMap.get(citation.unit)?.zh.includes(citation.quote)) throw new Error(`Quotation for ${check.id} is not in its Chinese source unit`);
    }
    if (check.verdict !== 'supported' && !report.findings.some(finding => finding.items.includes(check.id))) throw new Error(`Failed check ${check.id} has no finding`);
    if (complete && check.verdict !== 'supported') throw new Error('Date approval contradicts a failed check');
  }
  const known = [...packet.items.map(item => item.id), ...packet.people.map(person => person.id)];
  for (const finding of report.findings) {
    exactMembers(finding.items, known, 'Finding references', false);
    if (!finding.items.length) throw new Error('Finding must identify affected records');
    nonempty(finding.problem, 'Date finding', 20);
    nonempty(finding.action, 'Date finding action', 20);
  }
  for (const reference of report.references) {
    if (reference.kind === 'external') {
      const url = new URL(reference.url);
      if (!['https:', 'http:'].includes(url.protocol)) throw new Error('External date source must use HTTP(S)');
      nonempty(reference.title, 'Reference title');
      nonempty(reference.quote, 'Reference excerpt');
      nonempty(reference.reason, 'Reference interpretation', 20);
      if (!Number.isFinite(Date.parse(reference.accessedAt)) || reference.sourceHash !== sha256(reference.quote)) throw new Error('External reference requires a dated, hash-pinned excerpt');
      continue;
    }
    validateDateAuditScope(reference.book, reference.chapter);
    nonempty(reference.unit, 'Reference unit');
    nonempty(reference.quote, 'Reference quote');
    if (!/^sha256:[a-f0-9]{64}$/.test(reference.sourceHash)) throw new Error('Reference requires a pinned source hash');
    nonempty(reference.reason, 'Reference interpretation', 20);
  }
  if (complete && (report.findings.length || unresolvedDateAuditItems(packet).length)) throw new Error('Unresolved chronology cannot be approved');
  if (!complete && !report.findings.length) throw new Error('Unapproved audit requires actionable findings');
  return report;
}

export function dateAuditReferencesCurrent(report, { dataDir = DATA_DIR } = {}) {
  return report.references.every(reference => {
    if (reference.kind === 'external') return reference.sourceHash === sha256(reference.quote);
    const file = path.join(dataDir, reference.book, `${reference.chapter}.json`);
    if (!fs.existsSync(file)) return false;
    const unit = contentUnits(readJson(file)).find(unit => unit.id === reference.unit);
    return unit && sha256(unit.zh) === reference.sourceHash && unit.zh.includes(reference.quote);
  });
}

export function dateAuditStatus(book, chapter, options = {}) {
  validateDateAuditScope(book, chapter);
  const peopleDir = options.peopleDir ?? PEOPLE_DIR;
  const file = path.join(peopleDir, 'date-audits', book, `${chapter}.json`);
  if (!fs.existsSync(file)) return { status: 'un-audited', auditVersion: DATE_AUDIT_VERSION };
  if (!fs.existsSync(path.join(options.dataDir ?? DATA_DIR, book, `${chapter}.json`)) ||
      !fs.existsSync(path.join(peopleDir, 'extractions', book, `${chapter}.json`))) return { status: 'stale', auditVersion: DATE_AUDIT_VERSION };
  const report = readJson(file);
  const packet = buildDateAuditPacket(book, chapter, options);
  if (report.auditVersion !== DATE_AUDIT_VERSION || report.sourceHash !== packet.sourceHash || report.extractionHash !== packet.extractionHash) return { status: 'stale', auditVersion: DATE_AUDIT_VERSION };
  validateDateAuditReport(report, packet);
  if (!dateAuditReferencesCurrent(report, options)) return { status: 'stale', auditVersion: DATE_AUDIT_VERSION };
  return { status: report.status, auditVersion: DATE_AUDIT_VERSION, reviewedAt: report.reviewedAt, findings: report.findings.length };
}

export function recordDateAudit(report, options = {}) {
  const packet = buildDateAuditPacket(report.book, report.chapter, options);
  validateDateAuditReport(report, packet);
  if (!dateAuditReferencesCurrent(report, options)) throw new Error('Date audit reference changed or quotation is unsupported');
  const peopleDir = options.peopleDir ?? PEOPLE_DIR;
  const file = path.join(peopleDir, 'date-audits', report.book, `${report.chapter}.json`);
  if (fs.existsSync(file)) {
    const old = readJson(file);
    writeJsonAtomic(path.join(peopleDir, 'date-audit-history', report.book, report.chapter, `${sha256(JSON.stringify(old)).slice(7)}.json`), old);
  }
  writeJsonAtomic(file, report);
  return dateAuditStatus(report.book, report.chapter, options);
}

import { loadCurrentIdentityEvidence } from './people-identity-evidence.mjs';
import fs from 'node:fs';
import path from 'node:path';
import { projectPeopleProduct } from '../compile-people-catalog.mjs';
import { loadProperNounMatcher } from './people-candidates.mjs';
import { loadValidatedPeopleChapter } from './people-validated-chapter.mjs';
import { ChapterIdentityReviewError, acceptedCatalogIdentityView, chapterIdentityInputs, readChapterIdentityBundle, chapterIdentityEvidenceScopes, validateChapterIdentityBundle, assertReviewedIdentityCoverage, applyReviewedIdentityUncertainty } from './people-chapter-identity.mjs';
import { DATA_DIR, PEOPLE_DIR, extractionPath, readJson } from './people-content.mjs';
import { DATE_AUDIT_VERSION, dateAuditStatus } from './people-date-audit.mjs';
import { editorialDecisionPath, validateAppliedEditorialDecisions } from './people-editorial-decisions.mjs';
import { assertPeopleCatalogPublicationState } from './people-publication.mjs';
import { readPeopleCatalog, readPeopleSiteIndex } from './people-generated-data.mjs';
import { assertIdentitySeal, identityInputSeal, peopleDigest } from './people-identity-seal.mjs';

export class PeopleScopeGateError extends Error {}

export function assertChapterGates(extraction, currentPromptVersion, dateStatus, editorialDocument) {
  const scope = `${extraction.book}:${extraction.chapter}`;
  if (!Number.isInteger(currentPromptVersion) || currentPromptVersion < 1 ||
      extraction.run?.promptVersion !== currentPromptVersion) throw new PeopleScopeGateError(`Invalid or legacy prompt version: ${scope}`);
  if (!Array.isArray(extraction.translationRepairs)) throw new PeopleScopeGateError(`Missing editorial repair accounting: ${scope}`);
  if (extraction.translationRepairs.some(repair => repair.status === 'proposed')) {
    throw new PeopleScopeGateError(`Pending translation repair: ${scope}`);
  }
  if (extraction.translationRepairs.some(repair => repair.status === 'applied') && !editorialDocument) {
    throw new PeopleScopeGateError(`Missing independent applied editorial history: ${scope}`);
  }
  if (editorialDocument) {
    if (editorialDocument.book !== extraction.book || editorialDocument.chapter !== extraction.chapter) {
      throw new PeopleScopeGateError(`Editorial history scope mismatch: ${scope}`);
    }
    validateAppliedEditorialDecisions(editorialDocument, extraction);
  }
  if (dateStatus?.status !== 'audited' || dateStatus.auditVersion !== DATE_AUDIT_VERSION) {
    throw new PeopleScopeGateError(`Current independent date audit is ${dateStatus?.status ?? 'missing'}: ${scope}`);
  }
}

export const assertScopedIdentity = assertReviewedIdentityCoverage;

// Shared qualification reconstructs facts only from current, strictly validated members.
// Ebook callers assert the authoritative product contract before entering here.
export function loadQualifiedPeopleScope(scopes, { skipUnqualified = false,
  expectedInputs = null } = {}) {
  const catalogPath = path.join(PEOPLE_DIR, 'generated', 'catalog.json');
  const catalog = readPeopleCatalog(catalogPath);
  const siteIndex = readPeopleSiteIndex(path.join(PEOPLE_DIR, 'generated', 'site-index.json'));
  assertPeopleCatalogPublicationState(catalog);
  if (siteIndex.schemaVersion !== 2 || catalog.complete !== siteIndex.complete) {
    throw new Error('Sealed catalog and current site index publication state are inconsistent');
  }
  const seal = readJson(`${catalogPath}.identity-seal.json`);
  const inputs = identityInputSeal();
  assertIdentitySeal(seal, catalog, siteIndex, inputs);
  const config = readJson(path.join(PEOPLE_DIR, 'config.json'));
  if (catalog.currentPromptVersion !== config.promptVersion || siteIndex.currentPromptVersion !== config.promptVersion ||
      catalog.generatedAt !== siteIndex.generatedAt) throw new Error('Sealed identity generation does not match current configuration');
  const matcher = loadProperNounMatcher();
  const corpus = { chapters: [], localPeople: new Map() };
  const gateEvidence = [];
  const holds = [];
  const workload = { scopeChapters: scopes.length, candidateChapters: 0, validatedChapters: 0 };
  const identityView = acceptedCatalogIdentityView(catalog), identityCertificates = [], sourceCache = new Map();
  for (const { book, chapter } of scopes) {
    if (!fs.existsSync(extractionPath(book, chapter))) {
      if (!skipUnqualified) throw new Error(`Missing scoped extraction: ${book}:${chapter}`);
      holds.push({ book, chapter, reason: 'missing-extraction' });
      continue;
    }
    if (skipUnqualified) {
      // Only exclusion hints come from the sealed compiler generation. Fresh
      // report status may shortlist a newly approved chapter without a rebuild;
      // it never grants approval. Every candidate below still passes full gates.
      const chapterId = `${book}:${chapter}`;
      const compiled = siteIndex.chapters[chapterId];
      if (!compiled || compiled.promptVersion !== config.promptVersion) {
        holds.push({ book, chapter, reason: 'missing-or-legacy-compiled-chapter' });
        continue;
      }
      if (compiled.mentions.length && !fs.existsSync(path.join(PEOPLE_DIR, 'identity-reviews', book, `${chapter}.json`))) {
        holds.push({ book, chapter, reason: 'missing-independent-person-dossier-review' });
        continue;
      }
      const dateFile = path.join(PEOPLE_DIR, 'date-audits', book, `${chapter}.json`);
      if (!fs.existsSync(dateFile)) {
        holds.push({ book, chapter, reason: 'missing-independent-date-audit' });
        continue;
      }
      const report = readJson(dateFile);
      if (report.auditVersion !== DATE_AUDIT_VERSION || report.status !== 'audited') {
        holds.push({ book, chapter, reason: `independent-date-audit-${report.status ?? 'invalid'}-v${report.auditVersion ?? 'missing'}` });
        continue;
      }
    }
    workload.candidateChapters += 1;
    try {
    const current = loadValidatedPeopleChapter(book, chapter, { properNounMatcher: matcher });
    const { raw, packet, extraction } = current;
    workload.validatedChapters += 1;
    const editorialFile = editorialDecisionPath(book, chapter);
    const editorial = fs.existsSync(editorialFile) ? readJson(editorialFile) : null;
    const dateStatus = dateAuditStatus(book, chapter);
    assertChapterGates(extraction, config.promptVersion, dateStatus, editorial);
    let identityCertificate = null, identityBundle = null;
    if (current.localPeople.size) {
      identityBundle = readChapterIdentityBundle(book, chapter);
      const evidenceSources = loadCurrentIdentityEvidence(identityBundle, current, matcher, sourceCache);
      identityCertificate = validateChapterIdentityBundle(identityView, evidenceSources, { book, chapter }, identityBundle, chapterIdentityInputs(book, chapter));
      assertScopedIdentity(current, identityView, [identityCertificate]);
    }
    const report = readJson(path.join(PEOPLE_DIR, 'date-audits', book, `${chapter}.json`));
    for (const person of extraction.people) {
      if (corpus.localPeople.has(person.localId)) throw new Error(`Duplicate scoped local person ${person.localId}`);
    }
    gateEvidence.push({ book, chapter, personCount: current.localPeople.size, inputFingerprint: packet.input.chapterFingerprint, inputUnitCount: packet.input.unitCount, extraction: peopleDigest(raw), source: peopleDigest(readJson(path.join(DATA_DIR, book, `${chapter}.json`))),
      editorial: peopleDigest(editorial), dateAudit: peopleDigest(report), identityReview: peopleDigest(identityBundle) });
    if (identityCertificate) identityCertificates.push(identityCertificate);
    corpus.chapters.push({ extraction });
    for (const [localId, person] of current.localPeople) corpus.localPeople.set(localId, person);
    } catch (error) {
      if (!skipUnqualified || !(error instanceof PeopleScopeGateError || error instanceof ChapterIdentityReviewError ||
          ['PeopleExtractionValidationError', 'EditorialDecisionValidationError'].includes(error.name))) throw error;
      holds.push({ book, chapter, reason: String(error.message) });
    }
  }
  assertScopedIdentity(corpus, identityView, identityCertificates);
  const roles = readJson(path.join(PEOPLE_DIR, 'curation', 'role-vocabulary.json'));
  const overrides = readJson(path.join(PEOPLE_DIR, 'curation', 'overrides.json'));
  const projected = projectPeopleProduct(corpus, catalog, new Map(roles.roles.map(role => [role.id, role.label])), overrides.people);
  applyReviewedIdentityUncertainty(projected.catalog, identityCertificates);
  if (!skipUnqualified && projected.catalog.people.length === 0) throw new Error('Certified product contains no people');
  if (identityInputSeal() !== inputs) throw new Error('Identity inputs changed while qualifying product');
  for (const evidence of gateEvidence) {
    const { book, chapter } = evidence;
    const editorialFile = editorialDecisionPath(book, chapter);
    const currentEditorial = fs.existsSync(editorialFile) ? readJson(editorialFile) : null;
    const report = readJson(path.join(PEOPLE_DIR, 'date-audits', book, `${chapter}.json`));
    const status = dateAuditStatus(book, chapter);
    if (evidence.extraction !== peopleDigest(readJson(extractionPath(book, chapter))) ||
        evidence.source !== peopleDigest(readJson(path.join(DATA_DIR, book, `${chapter}.json`))) ||
        evidence.editorial !== peopleDigest(currentEditorial) || evidence.dateAudit !== peopleDigest(report) ||
        status.status !== 'audited' || status.auditVersion !== DATE_AUDIT_VERSION ||
        evidence.identityReview !== peopleDigest(identityCertificates.some(certificate => certificate.scope.book === book && certificate.scope.chapter === chapter) ? readChapterIdentityBundle(book, chapter) : null)) {
      throw new Error(`Editorial/date evidence changed while qualifying ${book}:${chapter}`);
    }
  }
  if (expectedInputs !== null && expectedInputs !== inputs) throw new Error('Qualified scope expected input pin is stale');
  return { ...projected, globalCatalog: catalog, holds, workload, gateEvidence, identityCertificates, identity: peopleDigest(seal), inputs };
}
